      {
        cursor-agent-cli = prev.stdenv.mkDerivation {
          pname = "cursor-agent-cli";
          inherit version;

          src =
            if spec == null then
              throw "cursor-agent-cli: unsupported system ${system}"
            else
              prev.fetchurl {
                url = "https://downloads.cursor.com/lab/${version}/${spec.os}/${spec.arch}/agent-cli-package.tar.gz";
